create extension if not exists btree_gist with schema extensions;
alter table public.foncier_land_leads add column if not exists priority_level text check(priority_level in('P1','P2','P3')),add column if not exists commercial_motivation integer check(commercial_motivation between 0 and 100),add column if not exists acquisition jsonb not null default '{}',add column if not exists ab_variant text,add column if not exists sheet_sync_status text not null default 'not_connected',add column if not exists sheet_sync_error text,add column if not exists sheet_synced_at timestamptz,add column if not exists retention_until timestamptz,add column if not exists processing_consent_at timestamptz,add column if not exists marketing_consent_at timestamptz,add column if not exists withdrawn_at timestamptz,add column if not exists commission_xpf numeric check(commission_xpf>=0);
alter table public.foncier_land_leads add column if not exists booking_token_hash text,add column if not exists report_token_hash text;
create index if not exists foncier_lead_phone_normalized_idx on public.foncier_land_leads(regexp_replace(phone,'\D','','g'));
create index if not exists foncier_lead_email_normalized_idx on public.foncier_land_leads(lower(email)) where email is not null;

create table public.foncier_funnel_events(id bigint generated always as identity primary key,created_at timestamptz not null default now(),session_id uuid not null,event_name text not null check(event_name in('landing_view','questionnaire_started','step_completed','parcel_selected','contact_shared','questionnaire_completed','appointment_viewed','appointment_booked','callback_requested','report_downloaded')),lead_id uuid references public.foncier_land_leads(id) on delete set null,page_path text,traffic_source text,utm jsonb not null default '{}',ab_variant text,metadata jsonb not null default '{}');
create index foncier_funnel_event_date_idx on public.foncier_funnel_events(created_at,event_name);

create table public.foncier_partial_submissions(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),expires_at timestamptz not null default now()+interval '30 days',resume_token_hash text unique not null,first_name text,phone text,email text,preferred_channel text,step integer not null default 1,payload jsonb not null default '{}',processing_consent boolean not null default false,follow_up_consent boolean not null default false,follow_up_status text not null default 'not_requested',converted_lead_id uuid references public.foncier_land_leads(id),last_reminded_at timestamptz);

create table public.foncier_availability(id uuid primary key default gen_random_uuid(),weekday integer not null check(weekday between 0 and 6),start_time time not null,end_time time not null,meeting_modes text[] not null default '{phone,video,on_site}',active boolean not null default true,check(start_time<end_time));
insert into public.foncier_availability(weekday,start_time,end_time) values(1,'09:00','16:00'),(2,'09:00','16:00'),(3,'09:00','16:00'),(4,'09:00','16:00'),(5,'09:00','15:00') on conflict do nothing;
create table public.foncier_appointments(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),lead_id uuid not null references public.foncier_land_leads(id) on delete cascade,start_at timestamptz not null,end_at timestamptz not null,timezone text not null default 'Pacific/Tahiti',mode text not null check(mode in('phone','video','on_site')),status text not null default 'confirmed' check(status in('confirmed','cancelled','completed','no_show')),notes text,confirmation_reference text unique not null default ('RDV-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))),exclude using gist(tstzrange(start_at,end_at,'[)') with &&) where(status='confirmed'));
create index foncier_appointment_start_idx on public.foncier_appointments(start_at);

create table public.foncier_notification_deliveries(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),lead_id uuid references public.foncier_land_leads(id) on delete cascade,channel text not null,event_name text not null,status text not null check(status in('delivered','failed','not_configured','pending')),provider_reference text,error text,payload_summary jsonb not null default '{}',last_attempt_at timestamptz not null default now(),attempts integer not null default 1);
create table public.foncier_reports(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),lead_id uuid not null references public.foncier_land_leads(id) on delete cascade,report_type text not null check(report_type in('owner','internal')),source_snapshot jsonb not null,verification_date date not null default current_date,storage_path text,status text not null default 'pending' check(status in('pending','generated','failed')),error text,unique(lead_id,report_type));

alter table public.foncier_activities add column if not exists responsible_user_id uuid references auth.users(id),add column if not exists reason text,add column if not exists lead_id uuid references public.foncier_land_leads(id) on delete cascade;
alter table public.foncier_funnel_events enable row level security;alter table public.foncier_partial_submissions enable row level security;alter table public.foncier_availability enable row level security;alter table public.foncier_appointments enable row level security;alter table public.foncier_notification_deliveries enable row level security;alter table public.foncier_reports enable row level security;
create policy "admin funnel analytics" on public.foncier_funnel_events for select to authenticated using(true);create policy "admin partials" on public.foncier_partial_submissions for all to authenticated using(true) with check(true);create policy "admin availability" on public.foncier_availability for all to authenticated using(true) with check(true);create policy "admin appointments" on public.foncier_appointments for all to authenticated using(true) with check(true);create policy "admin deliveries" on public.foncier_notification_deliveries for select to authenticated using(true);create policy "admin reports" on public.foncier_reports for all to authenticated using(true) with check(true);

create or replace function public.classify_foncier_lead() returns trigger language plpgsql set search_path=public as $$declare score integer:=20;begin
score:=score+case when new.owner_goal in('Vendre à un promoteur','Vendre au meilleur prix possible') then 25 when new.owner_goal in('Étudier une division','Conserver une partie du terrain','Valoriser un terrain familial') then 15 else 5 end;
score:=score+case when new.timeline in('Immédiatement','Dans les 3 mois') then 20 when new.timeline in('Dans les 6 mois','Dans l''année') then 10 else 3 end;
score:=score+case when new.access ilike '%direct%' then 12 when new.access ilike '%difficile%' then 0 else 5 end;
score:=score+case when new.surface>=2000 then 10 when new.surface>0 then 6 else 0 end;
score:=score+case when new.legal_status='Propriétaire unique' then 10 when new.legal_status in('Plusieurs propriétaires','Indivision') then 5 else 2 end;
new.commercial_motivation:=least(score,100);new.priority_level:=case when score>=75 then 'P1' when score>=50 then 'P2' else 'P3' end;new.processing_consent_at:=case when new.privacy_consent then coalesce(new.processing_consent_at,now()) end;new.marketing_consent_at:=case when new.marketing_consent then coalesce(new.marketing_consent_at,now()) end;new.retention_until:=coalesce(new.retention_until,now()+interval '24 months');return new;end$$;
create trigger foncier_classify_lead before insert or update of owner_goal,timeline,access,surface,legal_status,privacy_consent,marketing_consent on public.foncier_land_leads for each row execute function public.classify_foncier_lead();

create or replace function public.foncier_conversion_metrics(date_from timestamptz default now()-interval '30 days') returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('landing_views',count(*) filter(where event_name='landing_view'),'started',count(*) filter(where event_name='questionnaire_started'),'completed',count(*) filter(where event_name='questionnaire_completed'),'appointments',count(*) filter(where event_name='appointment_booked'),'conversion_rate',case when count(*) filter(where event_name='questionnaire_started')=0 then 0 else round(100.0*count(*) filter(where event_name='questionnaire_completed')/count(*) filter(where event_name='questionnaire_started'),1) end,'by_source',coalesce((select jsonb_object_agg(traffic_source,total) from(select coalesce(traffic_source,'direct')traffic_source,count(*)total from public.foncier_funnel_events where created_at>=date_from and event_name='landing_view' group by 1)s),'{}'::jsonb),'by_variant',coalesce((select jsonb_object_agg(ab_variant,data) from(select coalesce(ab_variant,'unknown')ab_variant,jsonb_build_object('views',count(*) filter(where event_name='landing_view'),'completed',count(*) filter(where event_name='questionnaire_completed'))data from public.foncier_funnel_events where created_at>=date_from group by 1)v),'{}'::jsonb)) from public.foncier_funnel_events where created_at>=date_from$$;
revoke all on function public.foncier_conversion_metrics(timestamptz) from public,anon;grant execute on function public.foncier_conversion_metrics(timestamptz) to authenticated;

insert into public.foncier_settings(id,value) values('conversion_funnel','{"status":"not_deployed","retention_months":24,"timezone":"Pacific/Tahiti","appointment_duration_minutes":45,"ab_test":{"active":true,"variants":["A","B","C"]},"notification_channels":{"internal":true,"external":"not_configured"}}'::jsonb) on conflict(id) do nothing;
